import java.sql.*;import java.nio.file.*;import java.util.*;import java.io.*;import java.lang.reflect.*;import com.alibaba.fastjson2.*;import org.apache.commons.lang3.SerializationUtils;import org.apache.commons.lang3.tuple.Pair;import webridge.wbridge.sql.ResultSetHolder;import webridge.wbridge.storedprocedure.SPConfig;import webridge.wbridge.storedprocedure.StoredProcedureManager;import webridge.wbridge.storedprocedure.invocation.SPInvokeManager;
/** Original WeBridge lifecycle: compile the reference's SQL region between SET and COMMIT. */
public class SetWeBridge extends AlignedWeBridge{
 static boolean recording,active,concolic;static JSONObject input;
 static void buffer(){for(String k:input.keySet()){if(k.equals("expected"))continue;Object v=input.get(k);SPInvokeManager.storeParam("REQUEST_PARAM_"+k,v);if(v instanceof String)SPInvokeManager.storeParam("M_L_String__REQUEST_PARAM_"+k,v);if(v instanceof Long)SPInvokeManager.storeParam("M_J_field_REQUEST_PARAM_"+k+"_java_lang_Long_value",v);}}
 static void clean()throws Exception{if(concolic){nativeCall("endConcolic",new Class<?>[]{});concolic=false;}SPInvokeManager.setUsingRecordedRs(false);ResultSetHolder.setInitialized(false);if(recording){SPInvokeManager.endRecording();recording=false;}if(active){SPInvokeManager.endApi();active=false;}}
 public static void main(String[]args){try{Files.createDirectories(out);String mode=args[0];if(mode.equals("synth")){StoredProcedureManager.run(args[1],home.resolve("aligned.conf").toString());return;}SnbSetSql.configure(Paths.get(System.getProperty("alignment.dir")));SPConfig.addConfig(home.resolve("aligned.conf").toFile());System.setProperty("spDefDir",home.resolve("generated/sql").toString());int idx=Integer.parseInt(args[1]);input=JSON.parseArray(new String(Files.readAllBytes(Paths.get(System.getProperty("alignment.dir")).resolve("inputs.json")),"UTF-8")).getJSONObject(idx);
 SnbSetSql.regionBoundary=new SnbSetSql.RegionBoundary(){public void enter(Connection c)throws Exception{
 if(mode.equals("record")){SPInvokeManager.startRecording();recording=true;}
 if(mode.equals("optimized")){SPInvokeManager.beginApi(api);active=true;SPInvokeManager.setInvokingSp(true);buffer();}
 if(mode.equals("replay")){ResultSetHolder.initialize(Files.readAllBytes(home.resolve("record-"+idx+".bin")));ResultSetHolder.setInitialized(true);SPInvokeManager.setUsingRecordedRs(true);nativeCall("startConcolic",new Class<?>[]{});concolic=true;for(String k:input.keySet())if(!k.equals("expected")){Object v=input.get(k);if(v instanceof String||v instanceof Long)nativeCall("symbolize",new Class<?>[]{Object.class,String.class},v,"REQUEST_PARAM_"+k);}}
 }public void leave(Connection c)throws Exception{
 if(mode.equals("record")){List<Pair<String,Object>>r=SPInvokeManager.getRecordedSqlAndResultSets();Files.write(home.resolve("record-"+idx+".bin"),SerializationUtils.serialize((Serializable)r));JSONArray sqls=new JSONArray();for(Pair<String,Object>p:r)sqls.add(p.getLeft());save("recorded-sql.json",sqls);SPInvokeManager.endRecording();recording=false;}
 if(mode.equals("replay")){String returned=(String)System.class.getMethod("weBridgeAnalysis",ClassLoader.class).invoke(null,SetWeBridge.class.getClassLoader());nativeCall("endConcolic",new Class<?>[]{});concolic=false;Files.copy(Paths.get("/tmp/webridgeMngr.tmp.sp.string"),out.resolve("graph.json"));save("graph-return-chars.json",returned.length());SPInvokeManager.setUsingRecordedRs(false);ResultSetHolder.setInitialized(false);}
 }};
 try(Connection c=DriverManager.getConnection(SnbSetSql.url,"root","")){save("connection-id.json",c.getClass().getMethod("getId").invoke(c));Map<String,Long>before=status(c);long start=System.nanoTime();JSONObject result=SnbSetSql.request(c,input);Map<String,Long>after=status(c);JSONObject report=new JSONObject();report.put("result",result);report.put("expected",input.getJSONObject("expected"));boolean ok=JSON.parseObject(result.toJSONString()).equals(input.getJSONObject("expected"));report.put("oracle_ok",ok);report.put("ms",(System.nanoTime()-start)/1e6);report.put("questions",after.get("Questions")-before.get("Questions")-1);report.put("source_calls",SnbSetSql.calls);report.put("status_delta",delta(before,after));report.put("sp_enabled_at_end",active&&SPInvokeManager.isInvokingSp());report.put("commands",SnbSetSql.commands);save("report.json",report);if(!ok)throw new IllegalStateException("Exact oracle mismatch");if(mode.equals("optimized")&&!SPInvokeManager.isInvokingSp())throw new IllegalStateException("SP disabled");}clean();System.exit(0);
 }catch(Throwable e){e.printStackTrace();try{clean();save("error.json",e.toString());}catch(Throwable x){e.addSuppressed(x);}System.exit(1);}}
}
